#include "Monstey_FearDbResources.hpp"
#include "Monstey_Json.hpp"
#include <array>
#include <fstream>
#include <iostream>
#include <random>
using namespace Monstey;
namespace {
using Monstey_U32=std::uint32_t;std::uint64_t Monstey_Groups=0,Monstey_Cases=0,Monstey_Checks=0;
void Monstey_Check(bool value,const char* text){++Monstey_Checks;if(!value)throw std::runtime_error(text);}
void Monstey_Put(Monstey_FearDbPackedImage& image,Monstey_U32 at,Monstey_U32 word){for(unsigned i=0;i<4;++i)image.allocation.at(at-image.base+i)=static_cast<std::uint8_t>(word>>(i*8));}
Monstey_U32 Monstey_Get(const Monstey_FearDbPackedImage& image,Monstey_U32 at){Monstey_U32 value=0;for(unsigned i=0;i<4;++i)value|=Monstey_U32(image.allocation.at(at-image.base+i))<<(i*8);return value;}
Monstey_FearDbPackedImage Monstey_Image(Monstey_U32 base,Monstey_U32 count){Monstey_FearDbPackedImage image;image.base=base;image.database=base+16;image.allocation.resize(64,0xa5);Monstey_Put(image,image.database,base);Monstey_Put(image,image.database+16,count);return image;}
Monstey_FearDbResources Monstey_Make(Monstey_U32 count){Monstey_FearDbResources resources;resources.allocations.push_back(Monstey_Image(0x1000,count));resources.allocations.push_back(Monstey_Image(0x2000,17));return resources;}
void Monstey_Null(){Monstey_FearDbResources r;r.cache={0,1,2};const auto cache=r.cache;auto result=Monstey_FearDbReleaseDatabase(r,0);Monstey_Check(result.kind==Monstey_FearDbReleaseKind::ignored_null&&r.cache==cache&&r.allocations.empty(),"null release consumes no memory or cache");++Monstey_Cases;++Monstey_Groups;}
void Monstey_Counter(){std::mt19937 rng(0x6d40);for(unsigned n=0;n<20000;++n){const auto count=n<5?std::array<Monstey_U32,5>{0,1,2,0x80000000,0xffffffff}[n]:rng();auto r=Monstey_Make(count);r.cache={0x2010,0x1010,0x1010,0x2010};const auto unrelated=r.allocations[1].allocation;auto result=Monstey_FearDbReleaseDatabase(r,0x1010);if(count==1){Monstey_Check(result.kind==Monstey_FearDbReleaseKind::freed&&result.counter_after==0&&result.allocation_base==0x1000,"last reference frees allocation");Monstey_Check(r.cache==std::vector<Monstey_U32>{0x2010,0x1010,0x2010}&&result.removed_cache_index==1,"erase first duplicate, preserve order");Monstey_Check(r.allocations.size()==1&&r.allocations[0].base==0x2000&&r.allocations[0].allocation==unrelated,"free only selected allocation");}else{Monstey_Check(result.kind==Monstey_FearDbReleaseKind::retained&&result.counter_after==count-1u,"wrapping decrement, nonzero retain");Monstey_Check(r.allocations.size()==2&&Monstey_Get(r.allocations[0],0x1020)==count-1u&&r.allocations[1].allocation==unrelated,"retained counter and other bytes");Monstey_Check(r.cache==std::vector<Monstey_U32>{0x2010,0x1010,0x1010,0x2010},"nonzero decrement does not touch cache");}++Monstey_Cases;}++Monstey_Groups;}
void Monstey_CacheOrder(){for(unsigned size=0;size<=12;++size)for(unsigned mask=0;mask<(1u<<size);++mask){auto r=Monstey_Make(1);std::vector<Monstey_U32> expected;std::size_t first=static_cast<std::size_t>(-1);for(unsigned i=0;i<size;++i){const auto value=(mask&(1u<<i))?0x1010u:0x2010u;r.cache.push_back(value);if(value==0x1010&&first==static_cast<std::size_t>(-1))first=i;else expected.push_back(value);}auto result=Monstey_FearDbReleaseDatabase(r,0x1010);Monstey_Check(result.kind==Monstey_FearDbReleaseKind::freed&&r.allocations.size()==1,"uncached/duplicate cache release still frees");Monstey_Check(r.cache==expected&&result.removed_cache_index==first,"all ordered duplicate masks");++Monstey_Cases;}++Monstey_Groups;}
void Monstey_RetainRegister(){for(auto count:std::array<Monstey_U32,5>{0,1,2,0x80000000,0xffffffff}){auto r=Monstey_Make(count);r.cache={0x1010};Monstey_FearDbRetainSelected(r,0x1010);Monstey_Check(Monstey_Get(r.allocations[0],0x1020)==count+1u&&r.cache==std::vector<Monstey_U32>{0x1010}&&r.allocations.size()==2,"selected retain only wraps counter");Monstey_FearDbRegisterLoaded(r,0x1010);Monstey_Check(Monstey_Get(r.allocations[0],0x1020)==count+2u&&r.cache==std::vector<Monstey_U32>{0x1010,0x1010},"registration appends duplicate then increments");++Monstey_Cases;}++Monstey_Groups;}
template<class Monstey_Call>void Monstey_Fault(Monstey_Call&&call,Monstey_U32 address,bool writing,Monstey_U32 width=4){bool caught=false;try{call();}catch(const Monstey_FearDbFault&e){caught=e.address==address&&e.writing==writing&&e.width==width;}Monstey_Check(caught,"first consumed owned range/free fault");}
void Monstey_Faults(){Monstey_FearDbResources r;r.cache={0x1010,0x2010};Monstey_Fault([&]{(void)Monstey_FearDbReleaseDatabase(r,0x1010);},0x1020,false);Monstey_Check(r.cache==std::vector<Monstey_U32>{0x1010,0x2010},"unavailable counter leaves cache unchanged");++Monstey_Cases;
 Monstey_FearDbPackedImage suffix;suffix.base=0x1020;suffix.allocation={1,0,0,0};r.allocations.push_back(suffix);Monstey_Fault([&]{(void)Monstey_FearDbReleaseDatabase(r,0x1010);},0x1010,false);Monstey_Check(r.cache==std::vector<Monstey_U32>{0x2010}&&r.allocations[0].allocation==std::vector<std::uint8_t>{0,0,0,0},"cache erase and counter precede allocation pointer load");++Monstey_Cases;
 auto bad=Monstey_Make(1);bad.cache={0x1010,0x1010};Monstey_Put(bad.allocations[0],0x1010,0x9999);Monstey_Fault([&]{(void)Monstey_FearDbReleaseDatabase(bad,0x1010);},0x9999,true,0);Monstey_Check(bad.cache==std::vector<Monstey_U32>{0x1010}&&bad.allocations.size()==2&&Monstey_Get(bad.allocations[0],0x1020)==0,"unknown free target preserves preceding decrement/erase");++Monstey_Cases;
 Monstey_FearDbResources missing;Monstey_Fault([&]{Monstey_FearDbRegisterLoaded(missing,0x1234);},0x1244,false);Monstey_Check(missing.cache==std::vector<Monstey_U32>{0x1234},"registration append precedes counter consumption");++Monstey_Cases;++Monstey_Groups;}
void Monstey_NullAllocation(){auto r=Monstey_Make(1);r.cache={0x1010};Monstey_Put(r.allocations[0],0x1010,0);const auto result=Monstey_FearDbReleaseDatabase(r,0x1010);Monstey_Check(result.kind==Monstey_FearDbReleaseKind::null_allocation&&r.allocations.size()==2&&r.cache.empty()&&Monstey_Get(r.allocations[0],0x1020)==0,"delete[] null consumes no allocation");++Monstey_Cases;++Monstey_Groups;}
void Monstey_FreeAddress(){auto r=Monstey_Make(1);r.cache={0x1010,0x2010};Monstey_Put(r.allocations[0],0x1010,0x2000);const auto result=Monstey_FearDbReleaseDatabase(r,0x1010);Monstey_Check(result.allocation_base==0x2000&&r.allocations.size()==1&&r.allocations[0].base==0x1000&&Monstey_Get(r.allocations[0],0x1020)==0,"free target is live stored base, not handle-derived allocation");Monstey_Check(r.cache==std::vector<Monstey_U32>{0x2010},"cache identity and stored allocation address are distinct");++Monstey_Cases;++Monstey_Groups;}
void Monstey_AfterFree(){auto r=Monstey_Make(1);r.cache={0x1010,0x1010};(void)Monstey_FearDbReleaseDatabase(r,0x1010);Monstey_Fault([&]{(void)Monstey_FearDbReleaseDatabase(r,0x1010);},0x1020,false);Monstey_Check(r.cache==std::vector<Monstey_U32>{0x1010}&&r.allocations.size()==1,"stale duplicate remains but freed bytes unavailable");++Monstey_Cases;++Monstey_Groups;}
void Monstey_LoadLifetime(){std::vector<std::uint8_t> bytes;for(auto word:std::array<Monstey_U32,8>{0x42444147,3,0,0,0,0,0,0})for(unsigned i=0;i<4;++i)bytes.push_back(static_cast<std::uint8_t>(word>>(i*8)));const auto original=bytes;Monstey_FearDbPackedInput input{bytes};auto load=Monstey_FearDbLoadPacked(input,std::array<std::uint8_t,2>{'x',0},0x5000);Monstey_Check(load.image.has_value(),"real loader lifetime composition");const auto db=load.image->database;Monstey_FearDbResources r;r.allocations.push_back(std::move(*load.image));Monstey_FearDbRegisterLoaded(r,db);Monstey_FearDbRetainSelected(r,db);Monstey_Check(Monstey_Get(r.allocations[0],db+16)==2&&r.cache==std::vector<Monstey_U32>{db},"loaded zero count then registration/retain");const auto first=Monstey_FearDbReleaseDatabase(r,db);Monstey_Check(first.kind==Monstey_FearDbReleaseKind::retained&&!r.allocations.empty(),"first release retains single allocation");const auto last=Monstey_FearDbReleaseDatabase(r,db);Monstey_Check(last.kind==Monstey_FearDbReleaseKind::freed&&r.allocations.empty()&&r.cache.empty()&&bytes==original,"last release frees owned allocation and leaves caller input");++Monstey_Cases;++Monstey_Groups;}
}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("NEW report required");Monstey_Null();Monstey_Counter();Monstey_CacheOrder();Monstey_RetainRegister();Monstey_Faults();Monstey_NullAllocation();Monstey_FreeAddress();Monstey_AfterFree();Monstey_LoadLifetime();std::ofstream(argv[1],std::ios::binary)<<Monstey_Json::object({{"schema","Monstey.FearDbResourceTests/1"},{"passed",true},{"groups",Monstey_Groups},{"cases",Monstey_Cases},{"checks",Monstey_Checks},{"synthetic_only",true},{"original_executed",false}}).dump(2)<<'\n';std::cout<<"PASS "<<Monstey_Groups<<" groups "<<Monstey_Cases<<" cases "<<Monstey_Checks<<" checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
